import React from "react";
import "../css/login.module.css";
import { Link } from "react-router-dom";
import { FaPhoneAlt, FaArrowLeft, FaArrowRight, FaKey } from "react-icons/fa";

class Login extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            step: "phone", // "phone" | "code"
            phone: "",
            phoneError: "",
            code: "",
            codeError: "",
        };
        this.phoneRef = React.createRef();
        this.codeRef = React.createRef();
    }

    handlePhoneSubmit = (e) => {
        e.preventDefault();
        const phone = this.phoneRef.current.value.trim();
        const cleanPhone = phone.replace(/\D/g, "");

        if (cleanPhone.length === 11) {
            this.setState({ phoneError: "", step: "code" }, () => {
                // focus on code input after step change
                this.codeRef.current.focus();
            });
        } else {
            this.setState({
                phoneError: "شماره موبایل باید ۱۱ رقم باشد",
            });
            this.phoneRef.current.focus();
        }
    };

    handleCodeSubmit = (e) => {
        e.preventDefault();
        const code = this.state.code.trim();
        // فرض می‌کنیم کد ۴ رقمی است
        if (code.length === 4 && /^\d{4}$/.test(code)) {
            this.setState({ codeError: "" });
            alert("کد تأیید صحیح است: " + code);
            // در اینجا می‌توانید به صفحه بعد بروید
        } else {
            this.setState({
                codeError: "کد باید ۴ رقم باشد",
            });
            this.codeRef.current.focus();
        }
    };

    handleCodeChange = (e) => {
        const value = e.target.value.replace(/\D/g, ""); // فقط عدد
        this.setState({ code: value, codeError: "" });
    };

    render() {
        return (
            <main className="container mt-4 pt-5">
                <Link to={"/welcome/"} className="back-link">
                    <FaArrowRight size={18} />
                </Link>

                <div className="align-items-center position-fixed top-50 start-50 translate-middle">
                    <div className="login-box-login shadow text-center item-back boder p-4 rounded-5 d-flex justify-content-center align-items-center">
                        <div className="welcome-box">
                            <img src="../img/aaa.png" alt="logo" />

                            {this.state.step === "phone" ? (
                                // مرحله ورود شماره موبایل
                                <div className="mt-5">
                                    <form className="mt-4" onSubmit={this.handlePhoneSubmit}>
                                        <div className="custom-floating">
                                            <FaPhoneAlt className="custom-icon" />
                                            <input
                                                type="tel"
                                                id="phone"
                                                className={`custom-input ${this.state.phoneError ? "is-invalid" : ""}`}
                                                placeholder=" "
                                                dir="rtl"
                                                value={this.state.phone}
                                                ref={this.phoneRef}
                                                onChange={(e) => {
                                                    this.setState({ phone: e.target.value });
                                                    if (this.state.phoneError) this.setState({ phoneError: "" });
                                                }}
                                            />
                                            <label htmlFor="phone" className="custom-label">
                                                شماره موبایل
                                            </label>
                                        </div>
                                        {this.state.phoneError && (
                                            <div className="text-danger text-end small mt-1">
                                                {this.state.phoneError}
                                            </div>
                                        )}
                                        <button type="submit" className="custom-btn">
                                            ارسال کد
                                        </button>
                                    </form>
                                </div>
                            ) : (
                                // مرحله ورود کد تأیید
                                <div className="mt-5">
                                    <form onSubmit={this.handleCodeSubmit}>
                                        <div className="custom-floating">
                                            <FaKey className="custom-icon" />
                                            <input
                                                type="text"
                                                id="code"
                                                className={`custom-input ${this.state.codeError ? "is-invalid" : ""}`}
                                                placeholder=" "
                                                dir="ltr"
                                                ref={this.codeRef}
                                                value={this.state.code}
                                                onChange={this.handleCodeChange}
                                                maxLength="4"
                                            />
                                            <label htmlFor="code" className="custom-label">
                                                کد تأیید
                                            </label>
                                        </div>
                                        {this.state.codeError && (
                                            <div className="text-danger text-end small mt-1">
                                                {this.state.codeError}
                                            </div>
                                        )}
                                        <button type="submit" className="custom-btn mt-3">
                                            تأیید کد
                                        </button>
                                    </form>
                                    <button
                                        className="btn btn-link mt-2"
                                        onClick={() =>
                                            this.setState({ step: "phone", code: "", codeError: "" })
                                        }
                                    >
                                        بازگشت به ویرایش شماره
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Login;
